1	package theme
2	
3	import (
4		"image/color"
5		"testing"
6	)
7	
8	// DEVDESK-764: every text colour of the palette reaches WCAG 1.4.3 (4.5:1) on
9	// the surface it is really painted on, on each of the 13 shipped themes. The
10	// measure of 2026-11-23 (docs/measurements/2026-11-23-sec-detail-contrast.md)
11	// found ColorDim, ColorSubTitleFg, ColorWarn and ColorFooterError below it.
12	//
13	// Surfaces, and why each colour is measured on the ones it has:
14	//
15	//   - background: ColorBackground, under everything (Rule 115).
16	//   - selected row: ColorTableLineSelected. A plain "normal" selection keeps
17	//     every cell's own foreground and repaints this background under it
18	//     (Rule 118, Rule 122), so any colour a table cell can take is read on it.
19	//   - raised surface: ColorCmdLineBg, which the chart, the inactive tab and the
20	//     disabled button sit on. It is the same hex as the selected row on every
21	//     shipped theme, but it is its own key, so it is measured on its own.
22	//
23	// ColorSubTitleFg only heads a block of text on the background. The footer
24	// colours are text on the background (the footer line); under the cursor they
25	// are the activity dot and the severity icon, a glyph held to 3:1 (WCAG 1.4.11).
26	const (
27		textMinContrast  = 4.5 // WCAG 1.4.3, text
28		glyphMinContrast = 3.0 // WCAG 1.4.11, graphical object
29	)
30	
31	type textInk struct {
32		what string
33		// key is the theme-file key that sets the colour ("" for a closed alias),
34		// read by TestSuggestTones only.
35		key string
36		fg  func() color.Color
37		// on lists the surfaces the colour is painted on and the ratio each needs.
38		on []surfaceNeed
39	}
40	
41	type surfaceNeed struct {
42		surface string
43		bg      func() color.Color
44		min     float64
45	}
46	
47	var (
48		onBackground = func(min float64) surfaceNeed {
49			return surfaceNeed{"ColorBackground", func() color.Color { return ColorBackground }, min}
50		}
51		onSelectedRow = func(min float64) surfaceNeed {
52			return surfaceNeed{"ColorTableLineSelected", func() color.Color { return ColorTableLineSelected }, min}
53		}
54		onRaised = func(min float64) surfaceNeed {
55			return surfaceNeed{"ColorCmdLineBg", func() color.Color { return ColorCmdLineBg }, min}
56		}
57	)
58	
59	// DEVDESK-770 part A: the colours the 2026-11-24 measure left under the bar.
60	// ColorSecondary is the header keys, the table header, the active-tab background
61	// and the activity dot, the update mark and the icons (a glyph, 3:1 on the
62	// selected row); ColorTableHeaderFg, ColorPrimary, ColorTitleFg and
63	// ColorAppTitleFg are text on the background. ColorViewportBorder is the frame
64	// border: a non-text object, 3:1 (WCAG 1.4.11) on the background it is drawn on
65	// (it falls back to ColorBorder, which is never painted on its own).
66	func textInks() []textInk {
67		allSurfaces := []surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast), onRaised(textMinContrast)}
68		return []textInk{
69			{"ColorText", "color_text", func() color.Color { return ColorText }, allSurfaces},
70			{"ColorDim", "color_dim", func() color.Color { return ColorDim }, allSurfaces},
71			{"ColorSubTitleFg", "subtitle_fg", func() color.Color { return ColorSubTitleFg },
72				[]surfaceNeed{onBackground(textMinContrast)}},
73			{"ColorWarn", "color_warn", func() color.Color { return ColorWarn },
74				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast)}},
75			{"ColorFooterWarn", "severity_medium", func() color.Color { return ColorFooterWarn },
76				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
77			{"ColorFooterError", "severity_critical", func() color.Color { return ColorFooterError },
78				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
79			{"ColorSecondary", "color_secondary", func() color.Color { return ColorSecondary },
80				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
81			{"ColorTableHeaderFg", "table_header_fg", func() color.Color { return ColorTableHeaderFg },
82				[]surfaceNeed{onBackground(textMinContrast)}},
83			{"ColorPrimary", "color_primary", func() color.Color { return ColorPrimary },
84				[]surfaceNeed{onBackground(textMinContrast)}},
85			{"ColorTitleFg", "title_fg", func() color.Color { return ColorTitleFg },
86				[]surfaceNeed{onBackground(textMinContrast)}},
87			{"ColorAppTitleFg", "app_title_fg", func() color.Color { return ColorAppTitleFg },
88				[]surfaceNeed{onBackground(textMinContrast)}},
89			{"ColorViewportBorder (frame border, non-text)", "viewport_border", func() color.Color { return ColorViewportBorder },
90				[]surfaceNeed{onBackground(glyphMinContrast)}},
91		}
92	}
93	
94	// textPair is a foreground painted on a background that is not one of the
95	// shared surfaces: both come from the same component.
96	type textPair struct {
97		what         string
98		fgKey, bgKey string
99		min          float64
100		get          func() (fg, bg color.Color)
101	}
102	
103	func styleColours(focused bool, variant string) func() (color.Color, color.Color) {
104		return func() (color.Color, color.Color) {
105			s := ButtonStyle(focused, variant)
106			return s.GetForeground(), s.GetBackground()
107		}
108	}
109	
110	// DEVDESK-770 part A. The LOW and HIGH badges and the gauge rail are part B and
111	// not held here.
112	func textPairs() []textPair {
113		return []textPair{
114			{"active tab (ColorTabActiveFg on ColorTabActiveBg)", "tab_active_fg", "tab_active_bg", textMinContrast,
115				func() (color.Color, color.Color) { return ColorTabActiveFg, ColorTabActiveBg }},
116			{"primary button, focused", "button_fg", "button_bg", textMinContrast, styleColours(true, "primary")},
117			{"primary button, unfocused", "button_inactive_fg", "button_inactive_bg", textMinContrast, styleColours(false, "primary")},
118			{"secondary button, unfocused", "button_inactive_fg", "button_inactive_bg", textMinContrast, styleColours(false, "secondary")},
119			{"command line, inactive (ColorCmdLineInactiveFg on ColorCmdLineBg)", "cmd_line_inactive_fg", "cmd_line_bg", textMinContrast,
120				func() (color.Color, color.Color) { return ColorCmdLineInactiveFg, ColorCmdLineBg }},
121		}
122	}
123	
124	// Each failure names the theme, the colour, the surface and the measured ratio.
125	func TestEveryTextColourReachesItsContrastOnEveryTheme(t *testing.T) {
126		eachShippedTheme(t, func(t *testing.T, name string) {
127			for _, ink := range textInks() {
128				for _, need := range ink.on {
129					fg, bg := ink.fg(), need.bg()
130					ratio, err := ContrastRatio(fg, bg)
131					if err != nil {
132						t.Errorf("theme %s: %s on %s: %v", name, ink.what, need.surface, err)
133						continue
134					}
135					if ratio < need.min {
136						t.Errorf("theme %s: %s %s on %s %s is %.2f:1, want >= %.1f:1",
137							name, ink.what, Hex(fg), need.surface, Hex(bg), ratio, need.min)
138					}
139				}
140			}
141		})
142	}
143	
144	// Each failure names the theme, the pair, both colours and the measured ratio.
145	func TestEveryTextPairReachesItsContrastOnEveryTheme(t *testing.T) {
146		eachShippedTheme(t, func(t *testing.T, name string) {
147			for _, p := range textPairs() {
148				fg, bg := p.get()
149				ratio, err := ContrastRatio(fg, bg)
150				if err != nil {
151					t.Errorf("theme %s: %s: %v", name, p.what, err)
152					continue
153				}
154				if ratio < p.min {
155					t.Errorf("theme %s: %s, %s on %s is %.2f:1, want >= %.1f:1",
156						name, p.what, Hex(fg), Hex(bg), ratio, p.min)
157				}
158			}
159		})
160	}
161	
162	// A greyed control still has to be read: raising ColorDim is not enough when the
163	// label sits on a background of the same hue. The disabled button used to paint
164	// ColorDim on ColorButtonInactiveBg, which is the same hex on nine themes (1:1).
165	func TestTheDisabledButtonLabelReachesTextContrastOnEveryTheme(t *testing.T) {
166		eachShippedTheme(t, func(t *testing.T, name string) {
167			for _, focused := range []bool{false, true} {
168				s := ButtonStyle(focused, "disabled")
169				fg, bg := s.GetForeground(), s.GetBackground()
170				ratio, err := ContrastRatio(fg, bg)
171				if err != nil {
172					t.Errorf("theme %s: disabled button (focused=%v): %v", name, focused, err)
173					continue
174				}
175				if ratio < textMinContrast {
176					t.Errorf("theme %s: disabled button (focused=%v) label %s on %s is %.2f:1, want >= %.1f:1",
177						name, focused, Hex(fg), Hex(bg), ratio, textMinContrast)
178				}
179			}
180		})
181	}
182	
183	// Grey says "not now", and colour alone must not be the only thing that says it
184	// (WCAG 1.4.1): a disabled button is italic, an enabled one is not, and the
185	// focus mark of a disabled button is an inversion rather than a colour only.
186	func TestTheDisabledButtonDiffersFromAnEnabledOneByMoreThanColour(t *testing.T) {
187		withTheme(t, DefaultTheme())
188		for _, focused := range []bool{false, true} {
189			dis, en := ButtonStyle(focused, "disabled"), ButtonStyle(focused, "primary")
190			if !dis.GetItalic() {
191				t.Errorf("focused=%v: the disabled button is not italic", focused)
192			}
193			if en.GetItalic() {
194				t.Errorf("focused=%v: the enabled button is italic: the signal would carry nothing", focused)
195			}
196		}
197		if on, off := ButtonStyle(true, "disabled"), ButtonStyle(false, "disabled"); sameColor(on.GetBackground(), off.GetBackground()) {
198			t.Error("a focused disabled button keeps the unfocused background: the focus would be invisible")
199		}
200	}
201	
202	// Rule 118: an inactive tab is ColorDim on the tab's own background. The theme
203	// files used to set tab_inactive_fg on its own, to a tone that was never held to
204	// 4.5:1 (1.4:1 on catppuccin-latte).
205	func TestTheInactiveTabLabelReachesTextContrastOnEveryTheme(t *testing.T) {
206		eachShippedTheme(t, func(t *testing.T, name string) {
207			ratio, err := ContrastRatio(ColorTabInactiveFg, ColorTabInactiveBg)
208			if err != nil {
209				t.Fatal(err)
210			}
211			if ratio < textMinContrast {
212				t.Errorf("theme %s: ColorTabInactiveFg %s on ColorTabInactiveBg %s is %.2f:1, want >= %.1f:1",
213					name, Hex(ColorTabInactiveFg), Hex(ColorTabInactiveBg), ratio, textMinContrast)
214			}
215		})
216	}
217	
218	// ColorFooterError and ColorFooterWarn alias the CRITICAL and MEDIUM badge
219	// backgrounds, so the badge foregrounds have to read on them too.
220	func TestTheCriticalAndMediumBadgesReachTextContrastOnEveryTheme(t *testing.T) {
221		eachShippedTheme(t, func(t *testing.T, name string) {
222			pairs := []struct {
223				what   string
224				fg, bg color.Color
225			}{
226				{"CRITICAL badge (ColorSeverityCriticalFg on ColorFooterError)", ColorSeverityCriticalFg, ColorFooterError},
227				{"MEDIUM badge (ColorSeverityMediumFg on ColorFooterWarn)", ColorSeverityMediumFg, ColorFooterWarn},
228			}
229			for _, p := range pairs {
230				ratio, err := ContrastRatio(p.fg, p.bg)
231				if err != nil {
232					t.Errorf("theme %s: %s: %v", name, p.what, err)
233					continue
234				}
235				if ratio < textMinContrast {
236					t.Errorf("theme %s: %s, %s on %s is %.2f:1, want >= %.1f:1",
237						name, p.what, Hex(p.fg), Hex(p.bg), ratio, textMinContrast)
238				}
239			}
240		})
241	}
242	
243	// A theme written before severity_low existed, or by hand, may leave both LOW
244	// keys out. The fallback pair has to stay readable: ColorDim is a light text
245	// tone since DEVDESK-764 and would give ColorText on ColorDim, about 2:1.
246	func TestAThemeWithoutSeverityLowKeepsAReadableLowBadge(t *testing.T) {
247		for name, th := range shippedThemes(t) {
248			t.Run(name, func(t *testing.T) {
249				bare := *th
250				bare.SeverityLow, bare.SeverityLowFg = "", ""
251				withTheme(t, &bare)
252				ratio, err := ContrastRatio(ColorSeverityLowFg, ColorSeverityLow)
253				if err != nil {
254					t.Fatal(err)
255				}
256				if ratio < textMinContrast {
257					t.Errorf("theme %s without severity_low: %s on %s is %.2f:1, want >= %.1f:1",
258						name, Hex(ColorSeverityLowFg), Hex(ColorSeverityLow), ratio, textMinContrast)
259				}
260			})
261		}
262	}
