type zzPair struct{ fg, bg string }

func zzAudit(frame, view string, into map[zzPair]map[string]bool, ex map[zzPair]string) {
	for _, row := range testutil.Cells(frame) {
		for _, c := range row {
			if strings.TrimSpace(c.Glyph) == "" || !strings.HasPrefix(c.FG, "#") || !strings.HasPrefix(c.BG, "#") {
				continue
			}
			r := []rune(c.Glyph)[0]
			if (r >= 0x2500 && r <= 0x259f) || unicode.IsSpace(r) {
				continue // frame lines and blocks: 3:1 objects, not text
			}
			ratio, err := theme.ContrastRatio(lipgloss.Color(c.FG), lipgloss.Color(c.BG))
			if err != nil || ratio >= 4.5 {
				continue
			}
			p := zzPair{c.FG, c.BG}
			if into[p] == nil {
				into[p] = map[string]bool{}
				ex[p] = c.Glyph
			}
			into[p][view] = true
		}
	}
}

func TestZZSGR(t *testing.T) {
	out := os.Getenv("SGR_OUT")
	if out == "" {
		t.Skip()
	}
	names := []string{"default", "catppuccin-frappe", "catppuccin-latte", "catppuccin-macchiato", "catppuccin-mocha", "dark-plus", "github-dark", "github-light", "nord", "one-dark", "solarized-dark", "solarized-light", "tokyo-night"}
	var sb strings.Builder
	t.Cleanup(func() { theme.ApplyTheme(theme.DefaultTheme()) })
	for _, name := range names {
		th, err := theme.LoadTheme(name)
		if err != nil {
			t.Fatal(err)
		}
		theme.ApplyTheme(theme.DefaultTheme())
		theme.ApplyTheme(th)
		pairs := map[zzPair]map[string]bool{}
		ex := map[zzPair]string{}
		for _, v := range []string{"workspaces", "security", "agent-usage", "configuration"} {
			a := routerAt(t, &fakeView{}, 140, 45)
			a.enterCommandMode()
			typeCommand(t, a, v)
			feedKey(t, a, testutil.Key("enter"))
			if string(a.currentView) == "dashboard" || a.currentView == "" {
				t.Fatalf("%s: view not reached (%s)", v, a.currentView)
			}
			zzAudit(a.Render(), v, pairs, ex)
		}
		for _, focusYes := range []bool{false, true} {
			m := components.NewConfirmModal("Delete?", "Delete the thing?")
			if focusYes {
				m.Update(testutil.Key("left"))
			}
			zzAudit(m.View(), "ConfirmModal", pairs, ex)
		}
		keys := make([]zzPair, 0, len(pairs))
		for p := range pairs {
			keys = append(keys, p)
		}
		sort.Slice(keys, func(i, j int) bool {
			if keys[i].fg != keys[j].fg {
				return keys[i].fg < keys[j].fg
			}
			return keys[i].bg < keys[j].bg
		})
		for _, p := range keys {
			ratio, _ := theme.ContrastRatio(lipgloss.Color(p.fg), lipgloss.Color(p.bg))
			var vs []string
			for v := range pairs[p] {
				vs = append(vs, v)
			}
			sort.Strings(vs)
			fmt.Fprintf(&sb, "%s|%s|%s|%.2f|%s|%q\n", name, p.fg, p.bg, ratio, strings.Join(vs, ","), ex[p])
		}
		if len(keys) == 0 {
			fmt.Fprintf(&sb, "%s|none\n", name)
		}
	}
	os.WriteFile(out, []byte(sb.String()), 0o644)
}
EOF
