import colorsys,math
def rgb(h): h=h.lstrip('#'); return [int(h[i:i+2],16)/255 for i in (0,2,4)]
def lin(c): return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
def L(h): r,g,b=[lin(x) for x in rgb(h)]; return .2126*r+.7152*g+.0722*b
def cr(a,b): x,y=sorted([L(a),L(b)],reverse=True); return (x+.05)/(y+.05)
def lab(h):
    r,g,b=[lin(x) for x in rgb(h)]
    X=(.4124*r+.3576*g+.1805*b)/.95047;Y=.2126*r+.7152*g+.0722*b;Z=(.0193*r+.1192*g+.9505*b)/1.08883
    f=lambda t:t**(1/3) if t>0.008856 else 7.787*t+16/116
    return (116*f(Y)-16,500*(f(X)-f(Y)),200*(f(Y)-f(Z)))
def de(a,b): return math.dist(lab(a),lab(b))
def hx(r,g,b): return '#%02x%02x%02x'%tuple(round(x*255) for x in (r,g,b))
def up(fg,bg,d=1):
    h,l,s=colorsys.rgb_to_hls(*rgb(fg)); 
    for i in range(1,201):
        l2=l+d*0.005*i
        if l2<0 or l2>1: return None
        c=hx(*colorsys.hls_to_rgb(h,l2,s))
        if cr(c,bg)>=4.5: return c
T={ # theme: (fg, orig bg, app bg, light?)
"frappe":("#c6d0f5","#626880","#303446"),
"macchiato":("#cad3f5","#5b6078","#24273a"),
"dark-plus":("#cccccc","#666666","#1e1e1e"),
"one-dark":("#abb2bf","#5c6370","#282c34"),
"solarized-dark":("#839496","#586e75","#002b36"),
}
for k,(fg,bg,app) in T.items():
    c=up(fg,bg)
    print(k,fg,bg,"shape",round(cr(bg,app),2),"cur",round(cr(fg,bg),2),"->",c, c and (round(de(fg,c),1), round(cr(c,bg),2)))
EOF

