package theme

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"charm.land/lipgloss/v2"
)

func TestZZMeasure(t *testing.T) {
	out := os.Getenv("MEASURE_OUT")
	if out == "" {
		t.Skip()
	}
	var sb strings.Builder
	eachShippedTheme(t, func(t *testing.T, name string) {
		for _, ink := range textInks() {
			for _, need := range ink.on {
				r, _ := ContrastRatio(ink.fg(), need.bg())
				fmt.Fprintf(&sb, "M|%s|%s on %s (%.1f)|%.2f|%s\n", name, ink.what, need.surface, need.min, r, Hex(ink.fg()))
			}
		}
		for _, p := range textPairs() {
			fg, bg := p.get()
			r, _ := ContrastRatio(fg, bg)
			fmt.Fprintf(&sb, "M|%s|%s (%.1f)|%.2f|%s on %s\n", name, p.what, p.min, r, Hex(fg), Hex(bg))
		}
		for _, v := range []string{"danger", "success", "default"} {
			s := ButtonStyle(false, v)
			r, _ := ContrastRatio(s.GetForeground(), s.GetBackground())
			fmt.Fprintf(&sb, "M|%s|%s button, unfocused (not held)|%.2f|%s on %s\n", name, v, r, Hex(s.GetForeground()), Hex(s.GetBackground()))
		}
		r, _ := ContrastRatio(ColorButtonInactiveBg, ColorBackground)
		fmt.Fprintf(&sb, "M|%s|SHAPE inactive button background on app background|%.2f|%s on %s\n", name, r, Hex(ColorButtonInactiveBg), Hex(ColorBackground))
	})
	if dir := os.Getenv("BEFORE_DIR"); dir != "" {
		after := shippedThemes(t)
		for name, th := range after {
			if name == "default" {
				continue
			}
			data, _ := os.ReadFile(filepath.Join(dir, name+".json"))
			var b Theme
			if err := json.Unmarshal(data, &b); err != nil {
				t.Fatal(err)
			}
			va, vb := reflect.ValueOf(th).Elem(), reflect.ValueOf(&b).Elem()
			for i := 0; i < va.NumField(); i++ {
				if va.Field(i).Kind() != reflect.String {
					continue
				}
				x, y := vb.Field(i).String(), va.Field(i).String()
				if x == y || !strings.HasPrefix(x, "#") {
					continue
				}
				tag, _, _ := strings.Cut(va.Type().Field(i).Tag.Get("json"), ",")
				de, _ := ColorDistance(lipgloss.Color(x), lipgloss.Color(y))
				fmt.Fprintf(&sb, "D|%s|%s|%s|%s|%.1f\n", name, tag, x, y, de)
			}
		}
	}
	os.WriteFile(out, []byte(sb.String()), 0o644)
}
EOF
